from pathlib import Path
import base64

ROOT = Path.cwd()
game_page = ROOT / "app/(portal)/game/page.tsx"
action_path = ROOT / "app/(portal)/game/house-of-chances-actions.ts"
panel_path = ROOT / "app/(portal)/game/components/HouseOfChancesPanel.tsx"

if not game_page.exists():
    raise SystemExit(f"Missing expected file: {game_page}")

text = game_page.read_text(encoding="utf-8")

import_anchor = 'import { OddJobsPanel, type OddJobStateRow } from "./components/OddJobsPanel";'
import_line = """import {
  HouseOfChancesPanel,
  type HouseOfChancesStateRow,
} from "./components/HouseOfChancesPanel";"""

if import_line not in text:
    if import_anchor not in text:
        raise SystemExit("Could not find OddJobsPanel import anchor.")
    text = text.replace(import_anchor, import_anchor + "\n" + import_line, 1)

promise_anchor = """  const oddJobsPromise =
    room.slug === "odd-jobs-bureau"
      ? supabase.rpc(
          "get_my_odd_jobs_state",
        )
      : Promise.resolve({
          data: [],
          error: null,
        });
"""

if "const houseOfChancesPromise =" not in text:
    if promise_anchor not in text:
        raise SystemExit("Could not find Odd Jobs promise anchor.")
    addition = promise_anchor + """
  const houseOfChancesPromise =
    room.slug === "house-of-chances"
      ? supabase.rpc(
          "get_my_house_of_chances_state",
        )
      : Promise.resolve({
          data: [],
          error: null,
        });
"""
    text = text.replace(promise_anchor, addition, 1)

old = """    headquartersManageData,
    oddJobsResult,
    breezeLodgingsResult,
"""
new = """    headquartersManageData,
    oddJobsResult,
    houseOfChancesResult,
    breezeLodgingsResult,
"""
if "houseOfChancesResult," not in text:
    if old not in text:
        raise SystemExit("Could not find Promise destructuring anchor.")
    text = text.replace(old, new, 1)

old = """    headquartersManageDataPromise,
    oddJobsPromise,
    breezeLodgingsPromise,
"""
new = """    headquartersManageDataPromise,
    oddJobsPromise,
    houseOfChancesPromise,
    breezeLodgingsPromise,
"""
if "houseOfChancesPromise,\n    breezeLodgingsPromise" not in text:
    if old not in text:
        raise SystemExit("Could not find Promise values anchor.")
    text = text.replace(old, new, 1)

old = """  const oddJobs =
    (oddJobsData ?? []) as OddJobStateRow[];

  const {
    data: breezeLodgingsData,
"""
new = """  const oddJobs =
    (oddJobsData ?? []) as OddJobStateRow[];

  const {
    data: houseOfChancesData,
    error: houseOfChancesError,
  } = houseOfChancesResult;

  if (houseOfChancesError) {
    throw new Error(
      `Unable to load House of Chances: ${houseOfChancesError.message}`,
    );
  }

  const houseOfChancesState =
    ((houseOfChancesData ?? [])[0] ?? null) as
      | HouseOfChancesStateRow
      | null;

  const {
    data: breezeLodgingsData,
"""
if "const houseOfChancesState =" not in text:
    if old not in text:
        raise SystemExit("Could not find House state parse anchor.")
    text = text.replace(old, new, 1)

old = """    {room.slug === "odd-jobs-bureau" ? (
      <OddJobsPanel jobs={oddJobs} />
    ) : null}
"""
new = """    {room.slug === "house-of-chances" && houseOfChancesState ? (
      <HouseOfChancesPanel state={houseOfChancesState} />
    ) : null}

    {room.slug === "odd-jobs-bureau" ? (
      <OddJobsPanel jobs={oddJobs} />
    ) : null}
"""
if "<HouseOfChancesPanel state={houseOfChancesState} />" not in text:
    if old not in text:
        raise SystemExit("Could not find Odd Jobs render anchor.")
    text = text.replace(old, new, 1)

game_page.write_text(text, encoding="utf-8")
action_path.write_bytes(base64.b64decode(""))
panel_path.write_bytes(base64.b64decode(""))

print("SUCCESS")
print("Patched player House of Chances experience.")
print("Next: npm run build")
